from typing import Any, Callable, Iterable, Literal, Mapping, TypedDict
from typing_extensions import ReadOnly

class Record(TypedDict):
    name: str
    count: int

value: Record = {"name": "ok", "count": 1}
class Other(TypedDict):
    count: int

other: Other = {"count": 2}
value.update(other)

